var spirit_default = '.ld-root:has(> .ld-shell) {\n  position: relative;\n}\n.ld-shell.ld-spirit-open {\n  grid-template-columns: 188px minmax(0, 1fr) 370px;\n}\n.ld-shell.ld-collapsed.ld-spirit-open {\n  grid-template-columns: 66px minmax(0, 1fr) 370px;\n}\n.ld-spirit-panel {\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n  min-height: 0;\n  height: 100%;\n  background: var(--ld-base);\n  border-left: 1px solid var(--ld-line);\n  padding: 24px 18px 18px;\n  overflow: hidden;\n}\n.ld-spirit-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n  margin-bottom: 15px;\n  flex: none;\n}\n.ld-spirit-heading {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n.ld-spirit-heading > svg {\n  color: var(--ld-accent);\n}\n.ld-spirit-heading strong {\n  font-size: 14px;\n}\n.ld-spirit-dot {\n  height: 6px;\n  width: 6px;\n  border-radius: 50%;\n  background: var(--dsw-alias-state-success-primary);\n  margin-left: 3px;\n}\n.ld-spirit-dot.working {\n  background: var(--ld-accent);\n}\n.ld-spirit-controls {\n  display: flex;\n  gap: 5px;\n}\n.ld-spirit-controls button {\n  width: 27px;\n  height: 27px;\n  font-size: 20px;\n  color: var(--ld-muted);\n  border-radius: 5px;\n}\n.ld-spirit-controls button:hover {\n  background: var(--dsw-alias-bg-layer-2);\n}\n.ld-spirit-model {\n  display: flex;\n  align-items: center;\n  gap: 7px;\n}\n.ld-spirit-model select {\n  flex: 1;\n  min-width: 0;\n  font-size: 11px;\n  padding: 7px;\n}\n.ld-spirit-model button {\n  width: 28px;\n  height: 28px;\n  color: var(--ld-muted);\n}\n.ld-spirit-model-caption {\n  font-size: 10px;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  color: var(--ld-muted);\n  margin: 7px 0 16px;\n}\n.ld-spirit-messages {\n  flex: 1;\n  min-height: 0;\n  overflow: auto;\n  padding: 8px 2px 15px;\n  scroll-behavior: smooth;\n  overflow-wrap: anywhere;\n}\n.ld-spirit-welcome {\n  padding: 30px 7px 20px;\n}\n.ld-spirit-welcome > .ld-spirit-art {\n  color: var(--ld-accent);\n  margin-bottom: 18px;\n}\n.ld-spirit-welcome h2 {\n  font-size: 21px;\n  line-height: 1.6;\n  font-weight: 500;\n  max-width: 250px;\n  margin-bottom: 12px;\n}\n.ld-spirit-welcome p {\n  font-size: 12px;\n  color: var(--ld-muted);\n  line-height: 1.9;\n}\n.ld-spirit-examples {\n  display: grid;\n  gap: 8px;\n  margin-top: 30px;\n}\n.ld-spirit-examples button {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 12px;\n  font-size: 11px;\n  line-height: 1.8;\n  text-align: left;\n  padding: 9px;\n  border: 1px solid var(--ld-line);\n  border-radius: 7px;\n}\n.ld-spirit-examples button span {\n  color: var(--ld-muted);\n  flex: none;\n}\n.ld-spirit-message {\n  font-size: 12px;\n  line-height: 1.9;\n  margin: 0 0 18px;\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n}\n.ld-spirit-message small {\n  display: block;\n  font-size: 10px;\n  color: var(--ld-muted);\n  margin-bottom: 5px;\n}\n.ld-spirit-user {\n  background: var(--dsw-alias-bg-layer-2);\n  padding: 10px 12px;\n  border-radius: 10px 10px 3px 10px;\n  margin-left: 22px;\n}\n.ld-spirit-assistant {\n  padding: 3px 3px 3px 0;\n}\n.ld-spirit-operation {\n  font-size: 10px;\n  color: var(--ld-muted);\n  padding: 6px 0;\n  display: flex;\n  gap: 7px;\n  align-items: flex-start;\n  flex-wrap: wrap;\n}\n.ld-spirit-operation p {\n  width: 100%;\n  font-size: 10px;\n  max-height: 100px;\n  overflow: auto;\n}\n.ld-operation-state {\n  font-size: 12px;\n  min-width: 12px;\n}\n.ld-operation-state.done {\n  color: var(--dsw-alias-state-success-primary);\n}\n.ld-operation-state.error,\n.ld-spirit-error,\n.ld-spirit-message.ld-spirit-error {\n  color: var(--dsw-alias-state-error-primary);\n}\n.ld-spirit-thinking {\n  font-size: 11px;\n  color: var(--ld-muted);\n  padding: 5px 0 15px;\n}\n.ld-spirit-thinking span {\n  margin-left: 5px;\n}\n.ld-spirit-error {\n  font-size: 11px;\n  border-top: 1px solid var(--ld-line);\n  padding: 9px 0;\n  overflow-wrap: anywhere;\n}\n.ld-spirit-error button {\n  margin-left: 8px;\n  font-size: 11px;\n  text-decoration: underline;\n}\n.ld-spirit-provider-errors {\n  font-size: 10px;\n  color: var(--ld-muted);\n  padding: 7px 0;\n  max-height: 100px;\n  overflow: auto;\n}\n.ld-spirit-provider-errors summary {\n  cursor: pointer;\n}\n.ld-spirit-compose {\n  flex: none;\n  border: 1px solid var(--dsw-alias-border-l2);\n  border-radius: 12px;\n  padding: 10px 11px;\n  background: var(--ld-surface);\n  margin-top: 8px;\n}\n.ld-spirit-compose textarea {\n  border: 0;\n  background: transparent;\n  padding: 0;\n  width: 100%;\n  min-height: 58px;\n  max-height: 170px;\n  resize: vertical;\n  font-size: 12px;\n  line-height: 1.8;\n}\n.ld-spirit-compose textarea:focus-visible {\n  outline: none;\n}\n.ld-spirit-compose:focus-within {\n  border-color: var(--ld-accent);\n}\n.ld-spirit-compose-foot {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 8px;\n  padding-top: 6px;\n}\n.ld-spirit-compose-foot > span {\n  font-size: 9px;\n  color: var(--ld-muted);\n}\n.ld-life-template-help {\n  margin-bottom: 10px !important;\n}\n.ld-life-templates {\n  margin-bottom: 24px;\n}\n.ld-life-filters {\n  border-top: 1px solid var(--ld-line);\n  padding-top: 18px;\n  margin-bottom: 23px;\n}\n.ld-life-filters .ld-btn {\n  border-color: transparent !important;\n  background: transparent !important;\n}\n.ld-life-filters .ld-btn[aria-pressed="true"] {\n  background: var(--dsw-alias-bg-layer-2) !important;\n}\n.ld-review-link summary {\n  font-size: 12px;\n  color: var(--ld-muted);\n  cursor: pointer;\n}\n.ld-review-link .ld-check-label {\n  margin-top: 8px;\n}\n.ld-dialog .ld-form + .ld-actions {\n  margin-top: 18px;\n}\n@container life-desk (max-width:1250px) {\n  .ld-shell.ld-spirit-open {\n    grid-template-columns: 160px minmax(0, 1fr) 340px;\n  }\n  .ld-shell.ld-collapsed.ld-spirit-open {\n    grid-template-columns: 66px minmax(0, 1fr) 340px;\n  }\n  .ld-spirit-open .ld-today-grid {\n    grid-template-columns: minmax(0, 1fr);\n  }\n  .ld-spirit-open .ld-support {\n    border-left: 0;\n    border-top: 1px solid var(--ld-line);\n    padding: 22px 0 0;\n  }\n  .ld-spirit-open .ld-page-top {\n    flex-wrap: wrap;\n  }\n}\n@container life-desk (max-width:950px) {\n  .ld-shell.ld-spirit-open,\n  .ld-shell.ld-collapsed.ld-spirit-open {\n    grid-template-columns: 60px minmax(0, 1fr);\n  }\n  .ld-spirit-panel {\n    position: absolute;\n    right: 0;\n    top: 0;\n    bottom: 0;\n    width: min(370px, calc(100% - 60px));\n    z-index: 30;\n    box-shadow: -12px 0 35px color-mix(in srgb, var(--ld-ink) 6%, transparent);\n  }\n  .ld-spirit-open .ld-nav button > span,\n  .ld-spirit-open .ld-brand > span {\n    display: none;\n  }\n  .ld-spirit-open .ld-nav-project {\n    display: none;\n  }\n  .ld-spirit-open .ld-nav button {\n    font-size: 0;\n    justify-content: center;\n    gap: 0;\n  }\n  .ld-spirit-open .ld-nav {\n    padding-inline: 8px;\n  }\n  .ld-spirit-open .ld-brand {\n    padding-inline: 8px;\n  }\n}\n@media (prefers-reduced-motion: reduce) {\n  .ld-spirit-messages {\n    scroll-behavior: auto;\n  }\n}\n';

// src/today.css
var today_default = "/* Tomato artwork uses fixed semantic fruit colors, independent of mood. */\n.ld-tomatoes {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  font-size: 11px;\n  color: var(--ld-muted);\n  margin-top: 5px;\n}\n.ld-tomatoes > span {\n  margin-left: 4px;\n  font-variant-numeric: tabular-nums;\n}\n.ld-tomato .fruit {\n  fill: color-mix(in srgb, var(--ld-muted) 12%, var(--ld-base));\n  stroke: var(--ld-muted);\n  stroke-width: 1.1;\n}\n.ld-tomato .leaf {\n  fill: none;\n  stroke: var(--ld-muted);\n  stroke-width: 1.3;\n  stroke-linecap: round;\n  stroke-linejoin: round;\n}\n.ld-tomato.ripe .fruit {\n  fill: #d9554f;\n  stroke: #b53b36;\n}\n.ld-tomato.ripe .leaf {\n  stroke: #587c58;\n}\n.ld-tomato.growing {\n  outline: 1px solid var(--ld-accent);\n  outline-offset: 2px;\n  border-radius: 50%;\n}\n.ld-focus-metrics {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  margin: 0 0 15px;\n}\n.ld-time-index {\n  display: flex;\n  width: 100%;\n  align-items: center;\n  gap: 13px;\n  text-align: left;\n  padding: 12px 0 !important;\n  border-bottom: 1px solid var(--ld-line) !important;\n  font-size: 12px !important;\n}\n.ld-time-index > span:first-child {\n  font-variant-numeric: tabular-nums;\n  color: var(--ld-muted);\n  flex: none;\n}\n.ld-time-index > span:nth-child(2) {\n  flex: 1;\n  min-width: 0;\n  overflow-wrap: anywhere;\n}\n.ld-time-index small {\n  color: var(--ld-muted);\n  font-size: 10px;\n}\n.ld-deadlines > h2 {\n  margin-bottom: 8px;\n}\n.ld-habit-group {\n  margin: 14px 0 20px;\n}\n.ld-habit-group h3 {\n  font-size: 11px;\n  color: var(--ld-muted);\n  font-weight: 500;\n}\n.ld-weekly-goals {\n  margin-top: 24px;\n  padding-top: 18px;\n  border-top: 1px solid var(--ld-line);\n}\n.ld-weekly-row {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 10px;\n  padding: 12px 0;\n}\n.ld-weekly-row > span {\n  display: flex;\n  flex-direction: column;\n  font-size: 12px;\n}\n.ld-weekly-row small {\n  color: var(--ld-muted);\n  font-size: 11px;\n}\n.ld-top-timer {\n  display: none;\n  position: sticky;\n  top: 0;\n  z-index: 15;\n  background: var(--ld-base);\n  border-bottom: 1px solid var(--ld-line);\n  padding: 10px 0;\n  margin-bottom: 18px;\n}\n.ld-not-today .ld-top-timer,\n.ld-spirit-open .ld-top-timer {\n  display: block;\n}\n.ld-spirit-open .ld-side-timer {\n  display: none;\n}\n.ld-focus-card.ld-focus-bar {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  flex-wrap: wrap;\n  border: 0;\n  padding: 0;\n  margin: 0;\n}\n.ld-focus-bar .ld-section-title,\n.ld-focus-bar .ld-progress {\n  display: none;\n}\n.ld-focus-bar .ld-time {\n  font-size: 24px;\n  line-height: 1.3;\n  margin: 0;\n  letter-spacing: -0.5px;\n}\n.ld-focus-bar .ld-timer-title {\n  max-width: 200px;\n}\n.ld-focus-bar .ld-focus-metrics {\n  margin: 0;\n  flex: 1;\n  min-width: 140px;\n}\n.ld-focus-bar .ld-timer-end {\n  width: 100%;\n  padding: 12px;\n  background: var(--ld-surface);\n  border: 1px solid var(--ld-line);\n  border-radius: 8px;\n}\n.ld-focus-bar .ld-timer-end .ld-field {\n  max-width: 220px;\n}\n.ld-side-timer {\n  position: sticky;\n  top: 0;\n  background: var(--ld-base);\n  z-index: 2;\n}\n@container life-desk (max-width:820px) {\n  .ld-top-timer {\n    display: block;\n    top: 0;\n  }\n  .ld-side-timer {\n    display: none;\n  }\n  .ld-support {\n    grid-template-columns: 1fr !important;\n  }\n  .ld-top-timer .ld-help {\n    font-size: 10px;\n  }\n}\n";

// src/focus.css
var focus_default = `/* Quiet timer controls inherit DSH tokens. The reader's explicit black theme is user-requested. */
.ld-timer-v2 {
  display: block !important;
  padding: 0 0 22px !important;
  margin: 0 0 24px !important;
  border-bottom: 1px solid var(--ld-line) !important;
}
.ld-timer-overview {
  display: flex;
  flex-direction: column;
  gap: 18px;
}
.ld-timer-context {
  display: flex;
  flex-direction: column;
  gap: 7px;
  min-width: 0;
}
.ld-timer-state {
  font-size: 11px;
  line-height: 1.6;
  color: var(--ld-muted);
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.ld-timer-state:before {
  content: "";
  display: inline-block;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--ld-muted);
}
.ld-timer-state.state-running:before {
  background: var(--ld-accent);
}
.ld-timer-state.state-finished:before {
  background: var(--dsw-alias-state-success-primary);
}
.ld-timer-task-name {
  font-size: 13px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ld-root .ld-timer-task-select {
  width: 100%;
  font-size: 12px;
  border-color: transparent;
  background: transparent;
  padding: 2px 0;
  color: var(--ld-ink);
}
.ld-timer-time {
  text-align: center;
}
.ld-timer-time-label {
  display: block;
  font-size: 10px;
  color: var(--ld-muted);
  margin-bottom: 5px;
  letter-spacing: 0.4px;
}
.ld-clock-digits {
  font-size: 50px;
  font-weight: 350;
  letter-spacing: -1.7px;
  line-height: 1.2;
  font-variant-numeric: tabular-nums;
}
.ld-clock-ring {
  position: relative;
  width: min(100%, 215px);
  aspect-ratio: 1;
  margin: auto;
}
.ld-clock-ring svg {
  display: block;
  width: 100%;
  height: 100%;
  fill: none;
  stroke: var(--ld-muted);
  stroke-width: 1;
}
.ld-clock-ring .ld-clock-track {
  stroke: var(--dsw-alias-bg-layer-2);
  stroke-width: 5;
}
.ld-clock-ring .ld-clock-arc {
  stroke: var(--ld-accent);
  stroke-width: 5;
  stroke-linecap: round;
}
.ld-clock-ring > span {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 35px;
  letter-spacing: -1px;
  font-weight: 350;
  font-variant-numeric: tabular-nums;
}
.ld-clock-flip {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  font-size: 33px;
  font-variant-numeric: tabular-nums;
  line-height: 1.4;
}
.ld-flip-tile {
  display: inline-flex;
  position: relative;
  justify-content: center;
  padding: 4px 8px;
  border-radius: 7px;
  background: var(--dsw-alias-bg-layer-2);
  min-width: 1.8em;
  perspective: 400px;
}
.ld-flip-tile:after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 50%;
  height: 1px;
  background: var(--ld-line);
}
.ld-flip-value {
  display: inline-block;
  animation: ld-clock-flip 0.18s ease-out;
}
.ld-flip-colon {
  color: var(--ld-muted);
  font-size: 0.65em;
}
.ld-clock-flip.static .ld-flip-value {
  animation: none;
}
@keyframes ld-clock-flip {
  from {
    transform: rotateX(-25deg);
    opacity: 0.65;
  }
  to {
    transform: rotateX(0);
    opacity: 1;
  }
}
.ld-clock-hourglass {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  font-size: 37px;
  letter-spacing: -1px;
  font-variant-numeric: tabular-nums;
}
.ld-clock-hourglass svg {
  height: 120px;
  width: auto;
}
.ld-hourglass-frame {
  fill: none;
  stroke: var(--ld-muted);
  stroke-width: 2;
  stroke-linecap: round;
}
.ld-sand {
  fill: var(--ld-accent);
  opacity: 0.7;
}
.ld-sand-stream {
  fill: none;
  stroke: var(--ld-accent);
  stroke-width: 1;
  opacity: 0.5;
}
.ld-timer-task-progress {
  display: flex;
  align-items: center;
  gap: 6px 9px;
  flex-wrap: wrap;
  font-size: 10px;
  color: var(--ld-muted);
  margin-top: 16px;
  line-height: 1.6;
}
.ld-timer-task-progress > span:first-child {
  font-weight: 550;
  flex: none;
}
.ld-timer-task-progress .ld-tomatoes {
  margin-top: 0;
}
.ld-timer-task-progress .ld-tomatoes > span {
  display: none;
}
.ld-timer-controls {
  position: relative;
  margin-top: 17px;
  min-width: 0;
}
.ld-timer-buttons {
  display: flex;
  gap: 8px;
  align-items: center;
  flex-wrap: wrap;
}
.ld-timer-buttons .ld-btn {
  font-size: 11px !important;
}
.ld-timer-preferences {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 5px 10px;
  margin-top: 12px;
}
.ld-timer-preferences > button {
  padding: 2px 0;
  font-size: 10px;
  color: var(--ld-muted);
  line-height: 1.6;
}
.ld-timer-preferences > button:hover {
  color: var(--ld-ink);
}
.ld-timer-preferences > button[aria-expanded="true"] {
  color: var(--ld-accent);
}
.ld-timer-drawer {
  background: var(--ld-surface);
  border: 1px solid var(--ld-line);
  border-radius: 9px;
  padding: 14px;
  margin-top: 12px;
  font-size: 12px;
  max-height: 55vh;
  overflow: auto;
  line-height: 1.7;
}
.ld-timer-drawer > strong {
  display: block;
  font-size: 12px;
  margin-bottom: 8px;
}
.ld-timer-drawer .ld-help {
  margin-bottom: 12px;
}
.ld-timer-drawer .ld-field {
  margin: 10px 0 14px;
}
.ld-duration-presets {
  display: flex;
  gap: 6px;
  margin: 10px 0;
  flex-wrap: wrap;
}
.ld-duration-presets > button {
  border: 1px solid var(--ld-line);
  border-radius: 6px;
  min-width: 34px;
  height: 32px;
  font-size: 12px;
}
.ld-duration-presets > button[aria-pressed="true"] {
  border-color: var(--ld-accent);
  color: var(--ld-accent);
  background: var(--dsw-alias-bg-layer-2);
}
.ld-face-options {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 9px;
  margin: 12px 0;
}
.ld-face-options > button {
  padding: 12px 7px;
  border: 1px solid var(--ld-line);
  border-radius: 8px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-height: 95px;
}
.ld-face-options > button[aria-pressed="true"] {
  border-color: var(--ld-accent);
  background: var(--dsw-alias-bg-layer-2);
}
.ld-face-options > button > span {
  font-size: 10px;
  color: var(--ld-muted);
}
.ld-face-options .ld-clock-digits {
  font-size: 22px;
  letter-spacing: -0.6px;
}
.ld-face-options .ld-clock-ring {
  width: 65px;
}
.ld-face-options .ld-clock-ring > span {
  font-size: 14px;
  letter-spacing: -0.4px;
}
.ld-face-options .ld-clock-flip {
  font-size: 16px;
}
.ld-face-options .ld-flip-tile {
  padding: 2px 3px;
  min-width: 0;
  border-radius: 4px;
}
.ld-face-options .ld-clock-hourglass {
  font-size: 15px;
  gap: 2px;
}
.ld-face-options .ld-clock-hourglass svg {
  height: 48px;
}
.ld-focus-stat {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  font-size: 11px;
  padding: 5px 0;
}
.ld-focus-stat > span {
  color: var(--ld-muted);
}
.ld-timer-v2.ld-timer-bar {
  display: grid !important;
  grid-template-columns: minmax(180px, 1fr) auto;
  gap: 9px 20px;
  align-items: center;
  border: 0 !important;
  padding: 0 !important;
  margin: 0 !important;
}
.ld-timer-bar .ld-timer-overview {
  grid-column: 1;
  grid-row: 1;
  display: grid;
  grid-template-columns: minmax(90px, 1fr) auto;
  align-items: center;
  gap: 22px;
}
.ld-timer-bar .ld-timer-context {
  gap: 2px;
}
.ld-timer-bar .ld-clock-digits {
  font-size: 34px;
  letter-spacing: -1px;
}
.ld-timer-bar .ld-timer-time-label {
  margin-bottom: 1px;
}
.ld-timer-bar .ld-timer-task-progress {
  grid-column: 1;
  grid-row: 2;
  margin-top: 0;
}
.ld-timer-bar .ld-timer-controls {
  grid-column: 2;
  grid-row: 1 / span 2;
  margin-top: 0;
  max-width: 360px;
}
.ld-timer-bar .ld-timer-buttons {
  justify-content: flex-end;
}
.ld-timer-bar .ld-timer-preferences {
  justify-content: flex-end;
  margin-top: 6px;
}
.ld-timer-bar .ld-timer-drawer {
  position: absolute;
  top: 100%;
  right: 0;
  width: min(390px, 75vw);
  max-height: 65vh;
  z-index: 30;
}
.ld-reader {
  --ld-base: #000;
  --ld-surface: #111315;
  --ld-ink: #ededeb;
  --ld-muted: #a5a6a7;
  --ld-line: #303236;
  --ld-accent: #e7e7e4;
  --dsw-alias-bg-layer-2: #1a1c20;
  --dsw-alias-border-l2: #45474d;
  --dsw-alias-state-success-primary: #a8c4ae;
  position: fixed;
  inset: 0;
  width: 100vw;
  height: 100dvh;
  background: #000;
  color: var(--ld-ink);
  z-index: 100000;
  pointer-events: auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  padding: 24px clamp(22px, 4vw, 70px);
  overflow: auto;
  outline: none !important;
}
/* Electron drag rectangles are independent of z-index. A fullscreen reader
   must subtract itself from underlying window-drag regions, including controls. */
.ld-reader,
.ld-reader * {
  -webkit-app-region: no-drag !important;
  app-region: no-drag !important;
}
/* Keep mode buttons below the native caption/drag band on macOS and Windows.
   Attribute specificity preserves this clearance in short/mobile layouts. */
.ld-reader[data-reader-mode] {
  padding-top: max(72px, env(safe-area-inset-top, 0px));
}
.ld-reader:fullscreen {
  width: 100%;
  height: 100%;
  background: #000;
}
.ld-reader-top {
  position: relative;
  z-index: 5;
  pointer-events: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  width: 100%;
  font-size: 11px;
  flex: none;
}
.ld-reader-top > div:last-child {
  display: flex;
  align-items: center;
  gap: 18px;
}
.ld-reader-top > div:last-child > span {
  color: var(--ld-muted);
  font-size: 10px;
}
.ld-reader-top button {
  padding: 6px 9px;
  border-radius: 6px;
  color: var(--ld-muted);
}
.ld-reader-top button:hover {
  color: var(--ld-ink);
  background: var(--ld-surface);
}
.ld-reader-mode {
  display: flex;
  gap: 5px;
}
.ld-reader-mode button[aria-pressed="true"] {
  color: var(--ld-ink);
  background: var(--ld-surface);
}
.ld-reader-display {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16px;
  flex: 1;
  padding: 25px 0;
  min-height: 0;
  max-width: 100%;
  text-align: center;
}
.ld-reader-caption {
  font-size: clamp(15px, 2.2vw, 29px);
  color: var(--ld-muted);
  max-width: 80vw;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ld-reader-display .ld-clock-digits {
  font-size: clamp(72px, 17vw, 280px);
  font-weight: 300;
  letter-spacing: -0.055em;
  line-height: 1.1;
  opacity: var(--reader-brightness, 0.9);
}
.ld-reader-display > .ld-clock-ring {
  width: clamp(220px, 48vmin, 560px);
  flex: none;
  opacity: var(--reader-brightness, 0.9);
}
.ld-reader-display > .ld-clock-ring > span {
  font-size: clamp(36px, 7vmin, 86px);
}
.ld-reader-display > .ld-clock-flip {
  font-size: clamp(42px, 10vw, 160px);
  gap: 10px;
  opacity: var(--reader-brightness, 0.9);
}
.ld-reader-display .ld-flip-tile {
  padding: 0.06em 0.2em;
  border-radius: 14px;
  min-width: 1.65em;
}
.ld-reader-display > .ld-clock-hourglass {
  flex-direction: row;
  gap: clamp(20px, 4vw, 70px);
  font-size: clamp(64px, 12vw, 210px);
  opacity: var(--reader-brightness, 0.9);
}
.ld-reader-display > .ld-clock-hourglass svg {
  height: clamp(150px, 28vh, 360px);
}
.ld-reader-remaining {
  color: var(--ld-muted);
  font-size: 12px;
  letter-spacing: 1px;
}
.ld-reader-current {
  font-size: 12px;
  color: var(--ld-muted);
  font-variant-numeric: tabular-nums;
  margin-top: 10px;
}
.ld-reader-display .ld-timer-task-progress {
  justify-content: center;
  font-size: 12px;
  margin-top: 4px;
  max-width: 85vw;
}
.ld-reader-display .ld-timer-state {
  font-size: 12px;
  min-height: 18px;
}
.ld-reader-bottom {
  width: min(720px, 100%);
  flex: none;
  margin-top: 10px;
}
.ld-reader-bottom > .ld-timer-controls {
  margin-top: 0;
}
.ld-reader-bottom .ld-timer-buttons,
.ld-reader-bottom .ld-timer-preferences {
  justify-content: center;
}
.ld-reader-bottom .ld-timer-preferences {
  margin-top: 12px;
}
.ld-reader-bottom > .ld-timer-controls > .ld-help {
  text-align: center;
}
.ld-reader-brightness {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 12px;
  margin-top: 18px;
  font-size: 10px;
  color: var(--ld-muted);
}
.ld-reader-brightness input[type="range"] {
  width: 110px;
  height: 14px;
  padding: 0;
  accent-color: var(--ld-muted);
  cursor: pointer;
}
.ld-reader-bottom > p {
  text-align: center;
  color: var(--ld-muted);
  font-size: 10px;
  margin-top: 10px;
}
.ld-reader-timer-controls .ld-timer-drawer {
  position: absolute;
  bottom: calc(100% + 15px);
  left: 50%;
  transform: translateX(-50%);
  width: min(420px, 86vw);
  max-height: 65vh;
  background: var(--ld-surface);
  z-index: 2;
}
.ld-reader-timer-controls .ld-face-options .ld-clock-digits {
  font-size: 22px;
}
.ld-reader-timer-controls .ld-face-options .ld-clock-flip {
  font-size: 16px;
}
.ld-reader-timer-controls .ld-face-options .ld-clock-ring {
  width: 65px;
}
.ld-reader-timer-controls .ld-face-options .ld-clock-ring > span {
  font-size: 14px;
}
.ld-reader-timer-controls .ld-face-options .ld-clock-hourglass {
  font-size: 15px;
}
.ld-reader-auto-hide {
  transition: opacity 0.25s ease;
}
.ld-reader.controls-hidden .ld-reader-auto-hide {
  opacity: 0;
}
.ld-reader.controls-hidden .ld-reader-auto-hide:focus-within {
  opacity: 1;
}
.ld-reader.reduce-motion .ld-flip-value {
  animation: none;
}
.ld-reader.reduce-motion .ld-reader-auto-hide {
  transition: none;
}
@container life-desk (max-width:700px) {
  .ld-timer-v2.ld-timer-bar {
    grid-template-columns: 1fr;
    gap: 9px;
  }
  .ld-timer-bar .ld-timer-controls {
    grid-column: 1;
    grid-row: 3;
    max-width: none;
  }
  .ld-timer-bar .ld-timer-buttons,
  .ld-timer-bar .ld-timer-preferences {
    justify-content: flex-start;
  }
  .ld-timer-bar .ld-timer-drawer {
    left: 0;
    right: auto;
    width: min(380px, 80vw);
  }
}
@media (max-width: 600px) {
  .ld-reader {
    padding: 16px;
  }
  .ld-reader-top {
    gap: 8px;
  }
  .ld-reader-top > div:last-child > span {
    display: none;
  }
  .ld-reader-top > div:last-child {
    gap: 5px;
  }
  .ld-reader-top button {
    font-size: 10px;
    padding: 5px;
  }
  .ld-reader-display > .ld-clock-hourglass {
    flex-direction: column;
    gap: 10px;
  }
  .ld-reader-display > .ld-clock-hourglass svg {
    height: 140px;
  }
  .ld-reader-display > .ld-clock-flip {
    gap: 4px;
  }
  .ld-reader-display .ld-flip-tile {
    border-radius: 7px;
  }
  .ld-reader-display {
    gap: 10px;
  }
  .ld-reader-bottom {
    margin-top: 0;
  }
  .ld-reader-current {
    margin-top: 2px;
  }
}
@media (max-height: 650px) {
  .ld-reader {
    padding-block: 12px;
  }
  .ld-reader-display {
    gap: 7px;
    padding: 10px 0;
  }
  .ld-reader-display > .ld-clock-ring {
    width: min(39vh, 320px);
  }
  .ld-reader-display > .ld-clock-hourglass svg {
    height: 120px;
  }
  .ld-reader-display .ld-clock-digits {
    font-size: min(17vw, 29vh);
  }
  .ld-reader-current {
    margin-top: 0;
  }
  .ld-reader-brightness {
    margin-top: 8px;
  }
  .ld-reader-bottom > p {
    margin-top: 5px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .ld-flip-value {
    animation: none !important;
  }
  .ld-reader-auto-hide {
    transition: none;
  }
}
`;

// src/planning.css
var planning_default = "/* Resident toolbar with a bounded capture sheet; the page remains the scroller. */\n.ld-toolbar-wrap {\n  position: relative;\n  min-width: 0;\n  z-index: 21;\n}\n.ld-toolbar-wrap .ld-page-top {\n  flex-wrap: wrap;\n}\n.ld-toolbar-wrap .ld-search {\n  min-width: 120px;\n}\n.ld-quick-panel {\n  position: absolute;\n  inset-inline: var(--ld-page-inline);\n  top: 100%;\n  z-index: 25;\n  padding: 20px;\n  border: 1px solid var(--ld-line);\n  border-radius: 12px;\n  background: var(--ld-base);\n  box-shadow: 0 12px 34px color-mix(in srgb, var(--ld-muted) 18%, transparent);\n  max-height: min(70vh, 480px);\n  overflow: auto;\n  -webkit-app-region: no-drag;\n}\n.ld-quick-panel fieldset {\n  border: 0;\n  padding: 0;\n  margin: 0;\n  min-width: 0;\n}\n.ld-capture-title {\n  display: flex;\n  gap: 8px;\n  align-items: center;\n}\n.ld-capture-title > input {\n  flex: 1;\n  min-width: 80px;\n  padding: 9px;\n  border: 1px solid var(--ld-line);\n  border-radius: 6px;\n  background: var(--ld-base);\n  color: var(--ld-ink);\n  font: inherit;\n}\n.ld-quick-panel summary {\n  font-size: 12px;\n  color: var(--ld-muted);\n  margin: 14px 0 8px;\n  cursor: pointer;\n}\n.ld-capture-fields {\n  margin: 12px 0;\n}\n.ld-plan-panel {\n  margin-bottom: 26px;\n  padding: 18px 20px;\n  border: 1px solid var(--ld-line);\n  border-radius: 12px;\n  background: color-mix(in srgb, var(--ld-accent) 4%, var(--ld-base));\n}\n.ld-plan-heading {\n  display: flex;\n  justify-content: space-between;\n  gap: 12px;\n  align-items: baseline;\n}\n.ld-plan-heading h2 {\n  margin: 0;\n}\n.ld-plan-heading > span {\n  font-size: 11px;\n  color: var(--ld-muted);\n}\n.ld-plan-stats {\n  display: grid;\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  gap: 16px;\n  margin: 18px 0;\n}\n.ld-plan-stats > div {\n  display: flex;\n  flex-direction: column;\n  gap: 5px;\n}\n.ld-plan-stats strong {\n  font-size: 26px;\n  font-weight: 500;\n  font-variant-numeric: tabular-nums;\n}\n.ld-plan-stats span {\n  font-size: 11px;\n  color: var(--ld-muted);\n}\n.ld-plan-capacity {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: end;\n  gap: 10px;\n}\n.ld-plan-capacity label {\n  display: flex;\n  gap: 10px;\n  align-items: center;\n  font-size: 12px;\n}\n.ld-plan-capacity input {\n  width: 90px;\n  padding: 6px 8px;\n  border: 1px solid var(--ld-line);\n  border-radius: 6px;\n  background: var(--ld-base);\n  color: var(--ld-ink);\n}\n.ld-plan-over {\n  color: var(--ld-accent);\n  font-weight: 600;\n}\n.ld-inbox-item {\n  border-bottom: 1px solid var(--ld-line);\n  padding: 16px 0;\n}\n.ld-inbox-heading {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n}\n.ld-inbox-heading .ld-task-body {\n  flex: 1;\n  min-width: 0;\n}\n.ld-task-tools {\n  flex-wrap: wrap;\n}\n@media (max-width: 600px) {\n  .ld-quick-panel {\n    inset-inline: 8px;\n    padding: 14px;\n  }\n  .ld-capture-title {\n    flex-wrap: wrap;\n  }\n  .ld-capture-title > input {\n    flex-basis: 100%;\n  }\n  .ld-plan-panel {\n    padding: 15px;\n  }\n  .ld-plan-stats {\n    gap: 10px;\n  }\n  .ld-plan-stats strong {\n    font-size: 22px;\n  }\n}\n";

